      if (normalized.includes('full actual')) return 'Full actual';
      if (normalized.includes('tail_db')) return 'tail_db';
      if (normalized.includes('bt scope')) return 'Phạm vi BT';
      if (normalized.includes('canonical pair')) return 'Cặp chuẩn';
